-- Open Mercy: complete database setup in ONE file.
-- Paste the whole file into the Supabase SQL Editor and press Run.
-- Generated by build-setup.sh from the files in this folder, in the order
-- listed in README.md. Do not edit this file; edit the source file and
-- regenerate. Every part is idempotent, so running it again is safe. If it
-- stops with an error, nothing is applied and the message names the
-- failing statement.

-- =====================================================================
-- 00-base-schema.sql
-- =====================================================================

-- Base schema: the two tables every other file in supabase/ builds on.
-- Run this FIRST in the Supabase SQL Editor of a fresh project, then the
-- rest in the order listed in supabase/README.md.
--
-- The original deployment created these tables by hand, outside version
-- control, so a fresh project had nothing for leaderboards-v2.sql,
-- presence.sql, results-hardening.sql and the rest to ALTER or read. The
-- columns here are exactly what the code writes and reads:
--   profiles      - authStore.ts (upsert id, username; select *), plus the
--                   columns later files add with `add column if not exists`
--                   (share_code, country, equipped_card_back, last_seen_at,
--                   avatar_version), which are left to those files.
--   game_results  - game-server/src/game.ts persistResults() and
--                   record_bot_result() in results-hardening.sql.
--
-- Idempotent: safe to re-run. Additive only.

-- ============================== profiles ==============================

create table if not exists public.profiles (
    id           uuid primary key references auth.users (id) on delete cascade,
    username     text not null unique,
    games_played integer not null default 0,
    games_won    integer not null default 0,
    created_at   timestamptz not null default now()
);

alter table public.profiles enable row level security;

-- Names, share codes and countries are public anyway (leaderboards, profile
-- pages, friend lists, avatars all read other players' rows), so anyone may
-- read a profile. Writes are your own row only; results-hardening.sql then
-- narrows WHICH columns a player may write.
drop policy if exists profiles_select_all on public.profiles;
create policy profiles_select_all on public.profiles
    for select to anon, authenticated using (true);

drop policy if exists profiles_insert_own on public.profiles;
create policy profiles_insert_own on public.profiles
    for insert to authenticated with check (id = auth.uid());

drop policy if exists profiles_update_own on public.profiles;
create policy profiles_update_own on public.profiles
    for update to authenticated using (id = auth.uid()) with check (id = auth.uid());

grant select on public.profiles to anon, authenticated;
grant insert, update on public.profiles to authenticated;

-- ============================ game_results ============================

create table if not exists public.game_results (
    id                     bigint generated always as identity primary key,
    game_id                text not null,
    user_id                uuid not null references auth.users (id) on delete cascade,
    opponent_count         integer not null default 1,
    result                 text not null check (result in ('won', 'lost', 'eliminated')),
    cards_remaining        integer not null default 0,
    peak_cards             integer not null default 0,
    draw_cards_played      integer not null default 0,
    wild_cards_played      integer not null default 0,
    cards_played_total     integer not null default 0,
    skips_dealt            integer not null default 0,
    swaps_made             integer not null default 0,
    draws_taken            integer not null default 0,
    biggest_stack_survived integer not null default 0,
    uno_calls              integer not null default 0,
    uno_penalties          integer not null default 0,
    game_duration_secs     integer not null default 0,
    is_bot_game            boolean not null default false,
    played_at              timestamptz not null default now(),
    created_at             timestamptz not null default now()
);

-- One row per player per game. This is also the daily's one-attempt rule:
-- a second 'daily-YYYY-MM-DD' result for the same player is a
-- unique_violation, which record_bot_result() reports as 'duplicate'.
create unique index if not exists game_results_game_user_idx
    on public.game_results (game_id, user_id);
create index if not exists game_results_user_played_idx
    on public.game_results (user_id, played_at desc);

-- Owner-select-only (see CLAUDE.md): every public read goes through a
-- SECURITY DEFINER function. Never widen this.
alter table public.game_results enable row level security;

drop policy if exists game_results_select_own on public.game_results;
create policy game_results_select_own on public.game_results
    for select to authenticated using (user_id = auth.uid());

-- Kept only until results-hardening.sql STEP 2 revokes direct inserts; after
-- that, solo results arrive via record_bot_result() and multiplayer results
-- via the game server's service-role key (which bypasses RLS).
drop policy if exists game_results_insert_own on public.game_results;
create policy game_results_insert_own on public.game_results
    for insert to authenticated with check (user_id = auth.uid());

grant select, insert on public.game_results to authenticated;

-- ===================== profile on signup (trigger) =====================

-- guest-profile-trigger.sql replaces this body with the full version (name
-- collision handling, guest support). It is defined here first only so the
-- trigger below can be created; no file in the repo created the trigger.
create or replace function public.create_profile_for_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
    if new.is_anonymous or new.email_confirmed_at is not null then
        insert into public.profiles (id, username)
        values (new.id, left(coalesce(nullif(new.raw_user_meta_data->>'username', ''), 'Player'), 11)
                        || '_' || left(new.id::text, 8))
        on conflict (id) do nothing;
    end if;
    return new;
exception when others then
    raise warning 'profile insert failed for user %: %', new.id, sqlerrm;
    return new;
end;
$$;

drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created
    after insert on auth.users
    for each row execute function public.create_profile_for_user();

-- Email signups get their profile when the address is confirmed.
drop trigger if exists on_auth_user_confirmed on auth.users;
create trigger on_auth_user_confirmed
    after update of email_confirmed_at on auth.users
    for each row when (old.email_confirmed_at is null and new.email_confirmed_at is not null)
    execute function public.create_profile_for_user();


-- =====================================================================
-- profile-hardening.sql
-- =====================================================================

-- profile-hardening.sql
-- Run manually in the Supabase SQL Editor. Two parts, both idempotent:
--   1) create_profile_for_user() survives a username collision instead of
--      leaving the user with no profile row.
--   2) Backfill profiles for existing auth users that have none.
-- Context: profiles.username is UNIQUE and the guest handle namespace filled
-- to the point that ~1 in 3 random handles collided; a collision made the
-- insert fail silently (no stats, no share code, no rank for that user).

-- 1) Trigger function: on a username collision, retry once with a suffix
--    derived from the user id - unique by construction, and the total stays
--    within the 20-char cap the client applies to names.
--    set search_path also clears the database-linter warning on this function.
create or replace function public.create_profile_for_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.email_confirmed_at is not null or new.confirmed_at is not null then
    begin
      insert into public.profiles (id, username)
      values (
        new.id,
        coalesce(new.raw_user_meta_data->>'username', split_part(new.email, '@', 1))
      )
      on conflict (id) do nothing;
    exception when unique_violation then
      insert into public.profiles (id, username)
      values (
        new.id,
        left(coalesce(nullif(new.raw_user_meta_data->>'username', ''), split_part(new.email, '@', 1), 'Player'), 11)
          || '_' || left(new.id::text, 8)
      )
      on conflict (id) do nothing;
    end;
  end if;
  return new;
end;
$$;

-- 2) Backfill: one row per auth user with no profile. The id-derived suffix
--    makes names unique against both existing rows and this batch (8 hex
--    chars; if this ever raises unique_violation, widen the suffix and rerun).
insert into public.profiles (id, username)
select
  u.id,
  left(coalesce(nullif(u.raw_user_meta_data->>'username', ''), 'Player'), 11)
    || '_' || left(u.id::text, 8)
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id)
on conflict (id) do nothing;

-- Verify: expect 0.
select count(*) as users_still_missing_profile
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id);


-- =====================================================================
-- guest-profile-trigger.sql
-- =====================================================================

-- Guest profiles, created by the database instead of the browser.
-- Run in the Supabase SQL Editor. Additive: replaces one function body and
-- backfills the rows it should already have created.
--
-- ALREADY RAN AN EARLIER VERSION OF THIS FILE? Re-run it. The whole file is
-- idempotent: `create or replace` is, and the backfill is guarded by
-- `where not exists`, so it inserts nothing the second time. Review moved the
-- collision path from a single id-fragment fallback to a readable 4-digit
-- suffix first, which only takes effect once the function is replaced again.
--
-- THE BUG
-- create_profile_for_user() gated every insert on
--     new.email_confirmed_at is not null or new.confirmed_at is not null
-- An anonymous user satisfies neither. `confirmed_at` is a GENERATED column
-- derived from the email and phone confirmation columns, and a guest has no
-- email and no phone, so both are null for every guest - measured: 0 of 530
-- anonymous users created in the last 7 days have confirmed_at set.
--
-- So this trigger has never created a guest profile. All 527 existing guest
-- profiles were written by ensureProfile() in authStore.ts, a client
-- round-trip on the critical path. When that call is lost - tab closed too
-- early, network blip, a token that was not refreshed yet - the player keeps
-- an account with no profile, permanently, and no server-side path repairs it.
-- That is the steady leak of roughly one account a day.
--
-- WHY THE GATE STAYS FOR EMAIL SIGNUPS
-- An unconfirmed address must not squat a username. So anonymous users are
-- added to the condition rather than replacing it.

create or replace function public.create_profile_for_user()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
    wanted    text;
    candidate text;
    attempt   int;
begin
    if not (
        new.is_anonymous
        or new.email_confirmed_at is not null
        or new.confirmed_at is not null
    ) then
        return new;
    end if;

    -- profiles.username is NOT NULL. A guest has no email, so the email
    -- fallback yields null for them and the literal is what actually lands.
    wanted := coalesce(
        nullif(new.raw_user_meta_data->>'username', ''),
        nullif(split_part(coalesce(new.email, ''), '@', 1), ''),
        'Player'
    );

    -- Three name forms, readable first. This trigger runs in the same
    -- transaction as the auth.users insert, so it now wins the race against
    -- ensureProfile() in authStore.ts and owns the collision path. That client
    -- retries with a fresh 4-digit suffix, so attempt 2 has to match it -
    -- jumping straight to the id fragment would turn a player who typed a
    -- taken `Rahul` into `Rahul_a1b2c3d4` rather than `Rahul1234`, and 15 to 31
    -- profiles a day are player-typed names, which are exactly the ones that
    -- collide.
    --
    -- Attempt 3 is unique by construction, so the loop effectively cannot fall
    -- through. That stays a logged warning rather than an assumption.
    --
    -- Nothing here may raise: this is AFTER INSERT on auth.users, so an
    -- exception would fail the sign-in itself. A player without a profile is
    -- recoverable and the client still repairs them; a player who cannot sign
    -- in is not. But every swallowed error is logged - the original leak went
    -- unnoticed for days precisely because there was no error to see.
    for attempt in 1..3 loop
        candidate := case attempt
            when 1 then wanted
            when 2 then left(wanted, 15) || floor(random() * 9000 + 1000)::text
            else        left(wanted, 11) || '_' || left(new.id::text, 8)
        end;

        begin
            insert into public.profiles (id, username)
            values (new.id, candidate)
            on conflict (id) do nothing;
            return new;
        exception
            when unique_violation then
                null; -- name taken, try the next form
            when others then
                raise warning 'profile insert failed for user % (%): %',
                    new.id, sqlstate, sqlerrm;
                return new;
        end;
    end loop;

    raise warning 'profile insert exhausted all name forms for user %', new.id;
    return new;
end;
$$;

-- Both triggers already exist and both call this function; neither needs to
-- change. on_auth_user_created covers guests from now on, and
-- on_auth_user_updated still covers an email confirmation later. A guest who
-- claims an account keeps the profile they already have, because every insert
-- here is `on conflict (id) do nothing`.

-- Backfill the accounts the old gate skipped. The suffixed form is used
-- unconditionally so the backfill cannot collide with a live username.
-- The gate is repeated here on purpose: an unconfirmed email signup is left
-- without a profile, which is the intended behaviour, not an oversight.
insert into public.profiles (id, username)
select
    u.id,
    left(coalesce(
        nullif(u.raw_user_meta_data->>'username', ''),
        nullif(split_part(coalesce(u.email, ''), '@', 1), ''),
        'Player'
    ), 11) || '_' || left(u.id::text, 8)
from auth.users u
where not exists (select 1 from public.profiles p where p.id = u.id)
  and (
    u.is_anonymous
    or u.email_confirmed_at is not null
    or u.confirmed_at is not null
  )
on conflict (id) do nothing;

-- Verify. `orphans` counts only accounts that SHOULD have a profile, so the
-- expected result is 0. `unconfirmed_held_back` is the count deliberately left
-- without one; a small number there is correct.
select
    (
        select count(*)
        from auth.users u
        where not exists (select 1 from public.profiles p where p.id = u.id)
          and (u.is_anonymous or u.email_confirmed_at is not null or u.confirmed_at is not null)
    ) as orphans,
    (
        select count(*)
        from auth.users u
        where not exists (select 1 from public.profiles p where p.id = u.id)
          and not (u.is_anonymous or u.email_confirmed_at is not null or u.confirmed_at is not null)
    ) as unconfirmed_held_back;


-- =====================================================================
-- cosmetics.sql
-- =====================================================================

-- Account-synced card-back equip. Run in the Supabase SQL Editor.
-- Additive only: one nullable column on profiles. The owner-update RLS
-- policy that already covers username covers this too.

alter table public.profiles
    add column if not exists equipped_card_back text;


-- =====================================================================
-- avatars.sql
-- =====================================================================

-- Profile pictures. Run in the Supabase SQL Editor. Additive and re-runnable.
--
-- A photo is two things: profiles.avatar_version (epoch ms of the current
-- photo, null = none) and the object avatars/<user id>/<version> in a public
-- bucket. A new photo is a new object, so its url changes with it and the CDN
-- can cache it forever; the client deletes the previous object after a save.
--
-- profiles is already readable by everyone and updatable by its owner, so the
-- column needs no policy. Guests could set the column on their own row, but
-- without an object behind it every client falls back to the initial.

alter table public.profiles
    add column if not exists avatar_version bigint;

-- results-hardening.sql grants profile updates column by column, so a new
-- column is read-only until it is listed. Without this the upload lands and
-- the save fails with "permission denied for table profiles".
grant update (avatar_version) on public.profiles to authenticated;

-- Small squares only: the client crops and re-encodes to 256px before upload.
-- A re-run re-applies the limits, which are the only server-side check on what
-- gets uploaded, even if the bucket was first made by hand.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('avatars', 'avatars', true, 262144, array['image/webp', 'image/jpeg'])
on conflict (id) do update set
    public = excluded.public,
    file_size_limit = excluded.file_size_limit,
    allowed_mime_types = excluded.allowed_mime_types;

-- Claimed accounts write inside their own folder. Anonymous (guest) sessions
-- are refused here, which is the real gate; the app's claim sheet only
-- explains it. A guest who claims keeps their user id, so the folder is theirs.
drop policy if exists avatars_insert_own on storage.objects;
create policy avatars_insert_own on storage.objects
    for insert to authenticated
    with check (
        bucket_id = 'avatars'
        and (storage.foldername(name))[1] = auth.uid()::text
        and coalesce((auth.jwt() ->> 'is_anonymous')::boolean, false) = false
    );

-- Storage's remove() needs select as well as delete on the rows it removes.
-- Scoped to your own folder; public reads go through the public url, not RLS.
drop policy if exists avatars_select_own on storage.objects;
create policy avatars_select_own on storage.objects
    for select to authenticated
    using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);

drop policy if exists avatars_delete_own on storage.objects;
create policy avatars_delete_own on storage.objects
    for delete to authenticated
    using (bucket_id = 'avatars' and (storage.foldername(name))[1] = auth.uid()::text);


-- =====================================================================
-- presence.sql
-- =====================================================================

-- Presence. Run in the Supabase SQL Editor. Additive: one column, one index,
-- three SECURITY DEFINER functions, three grants. No table is dropped, and
-- re-running the whole file is safe.
--
-- One column answers three questions - "is this player online?", "when were
-- they last here?", and "how many are playing right now?". The client checks
-- in through touch_presence() on load and every 60s while its tab is visible.
--
-- What this exposes: a last-seen timestamp per user id, to anyone who already
-- has that id. Ids are public today through the leaderboards and profile
-- pages, so this adds a timestamp, not an identity.
--
-- The read is granted to `anon` on purpose, and the cost is understood: a
-- shared profile link shows last-seen to a visitor who is not signed in, and
-- a script that knows a user id can poll it and learn when that player is
-- usually around. The invite case won the call - a link that says "online
-- now" to whoever opens it is the point. Narrowing this to accepted friends
-- stays available once the friendships table lands.

alter table profiles add column if not exists last_seen_at timestamptz;

create index if not exists profiles_last_seen_idx on profiles (last_seen_at desc);

-- The check-in. The server supplies the time, so one clock decides both the
-- write and the two reads below.
--
-- The client could update its own row directly - owner-update RLS allows it -
-- but then the timestamp would be whatever the browser believes, and a device
-- with a wrong clock would be permanently online or permanently offline. It
-- would also be settable by hand: a future value reads as ONLINE NOW forever.

create or replace function public.touch_presence()
returns void
language sql
security definer
set search_path = public
as $$
    update profiles set last_seen_at = now() where id = auth.uid()
$$;

-- Signed in only, and it writes exactly one row - the caller's own. Guests
-- count: an anonymous Supabase user is authenticated.
--
-- Both PUBLIC and anon have to be named: a new function is granted EXECUTE
-- to PUBLIC by Postgres and to anon by the project's default privileges, and
-- revoking one leaves the other. Even so, a call that got through would
-- update zero rows, because auth.uid() is null. The two reads below keep
-- their open grants deliberately.
revoke execute on function public.touch_presence() from public, anon;
grant execute on function public.touch_presence() to authenticated;

-- Two minutes, not one: the heartbeat runs every 60s, so one missed beat must
-- not flip a present player to offline. Keep this in step with
-- ONLINE_WINDOW_MS in frontend/src/utils/relativeTime.ts.

create or replace function public.players_presence(ids uuid[])
returns table (user_id uuid, last_seen_at timestamptz)
language sql
security definer
set search_path = public
stable
as $$
    select id, last_seen_at
    from profiles
    where id = any(ids)
$$;

grant execute on function public.players_presence to anon, authenticated;

-- The live population. Counts players, not sockets: a player with two tabs
-- open is one row.

create or replace function public.online_now()
returns int
language sql
security definer
set search_path = public
stable
as $$
    select count(*)::int
    from profiles
    where last_seen_at > now() - interval '2 minutes'
$$;

grant execute on function public.online_now to anon, authenticated;


-- =====================================================================
-- leaderboards-v2.sql
-- =====================================================================

-- Leaderboards v2 — identity, cosmetics, and rank context for the full-page
-- boards. Run in the Supabase SQL Editor (replaces both v1 board functions;
-- the return type changed, hence drop + recreate). Table changes are
-- additive: two nullable profile columns. The share_code default backfills
-- existing rows with distinct codes.
--
-- Re-run after adding badges: both board functions now also return user_id
-- so the client can look up each row's badge via player_points (badges.sql).

-- Shareable, rename-safe identity for /p/<code> profile URLs.
alter table public.profiles
    add column if not exists share_code text unique
    default substr(md5(random()::text || clock_timestamp()::text), 1, 8);

-- ISO-3166 alpha-2, captured client-side from the CDN's country lookup.
alter table public.profiles
    add column if not exists country text;

drop function if exists public.daily_leaderboard(date, int);

create or replace function public.daily_leaderboard(
    challenge_date date default (now() at time zone 'utc')::date,
    max_rows int default 50
)
returns table (
    rank bigint,
    user_id uuid,
    username text,
    share_code text,
    country text,
    skin text,
    lifetime_wins bigint,
    result text,
    effort int,
    duration_secs int,
    is_me boolean
)
language sql
security definer
set search_path = public
stable
as $$
    select
        row_number() over (
            order by (gr.result = 'won') desc,
                     (gr.cards_played_total + gr.draws_taken) asc,
                     gr.game_duration_secs asc
        ) as rank,
        gr.user_id,
        coalesce(p.username, 'PLAYER') as username,
        p.share_code,
        p.country,
        p.equipped_card_back as skin,
        (select count(*) from game_results w
          where w.user_id = gr.user_id and w.result = 'won') as lifetime_wins,
        gr.result,
        (gr.cards_played_total + gr.draws_taken) as effort,
        gr.game_duration_secs as duration_secs,
        (auth.uid() is not null and gr.user_id = auth.uid()) as is_me
    from game_results gr
    left join profiles p on p.id = gr.user_id
    where gr.game_id = 'daily-' || to_char(challenge_date, 'YYYY-MM-DD')
    order by 1
    limit max_rows;
$$;

grant execute on function public.daily_leaderboard to anon, authenticated;

drop function if exists public.weekly_wins_leaderboard(int);

create or replace function public.weekly_wins_leaderboard(max_rows int default 50)
returns table (
    rank bigint,
    user_id uuid,
    username text,
    share_code text,
    country text,
    skin text,
    lifetime_wins bigint,
    wins bigint,
    games bigint,
    is_me boolean
)
language sql
security definer
set search_path = public
stable
as $$
    select
        row_number() over (
            order by count(*) filter (where gr.result = 'won') desc,
                     count(*) asc
        ) as rank,
        gr.user_id,
        coalesce(p.username, 'PLAYER') as username,
        p.share_code,
        p.country,
        p.equipped_card_back as skin,
        (select count(*) from game_results w
          where w.user_id = gr.user_id and w.result = 'won') as lifetime_wins,
        count(*) filter (where gr.result = 'won') as wins,
        count(*) as games,
        (auth.uid() is not null and gr.user_id = auth.uid()) as is_me
    from game_results gr
    left join profiles p on p.id = gr.user_id
    where gr.played_at > now() - interval '7 days'
    group by gr.user_id, p.username, p.share_code, p.country, p.equipped_card_back
    having count(*) filter (where gr.result = 'won') > 0
    order by 1
    limit max_rows;
$$;

grant execute on function public.weekly_wins_leaderboard to anon, authenticated;

-- Rank context for the viewer: their position and the field size, even when
-- they sit far below the visible top rows.

create or replace function public.daily_my_rank(
    challenge_date date default (now() at time zone 'utc')::date
)
returns table (my_rank bigint, total_players bigint)
language sql
security definer
set search_path = public
stable
as $$
    with ranked as (
        select gr.user_id,
               row_number() over (
                   order by (gr.result = 'won') desc,
                            (gr.cards_played_total + gr.draws_taken) asc,
                            gr.game_duration_secs asc
               ) as rnk
        from game_results gr
        where gr.game_id = 'daily-' || to_char(challenge_date, 'YYYY-MM-DD')
    )
    select
        (select min(rnk) from ranked where auth.uid() is not null and user_id = auth.uid()),
        (select count(*) from ranked);
$$;

grant execute on function public.daily_my_rank to anon, authenticated;

create or replace function public.weekly_my_rank()
returns table (my_rank bigint, total_players bigint)
language sql
security definer
set search_path = public
stable
as $$
    with ranked as (
        select gr.user_id,
               row_number() over (
                   order by count(*) filter (where gr.result = 'won') desc,
                            count(*) asc
               ) as rnk
        from game_results gr
        where gr.played_at > now() - interval '7 days'
        group by gr.user_id
        having count(*) filter (where gr.result = 'won') > 0
    )
    select
        (select min(rnk) from ranked where auth.uid() is not null and user_id = auth.uid()),
        (select count(*) from ranked);
$$;

grant execute on function public.weekly_my_rank to anon, authenticated;


-- =====================================================================
-- leaderboards-alltime.sql
-- =====================================================================

-- All-time leaderboard. Run in the Supabase SQL Editor AFTER
-- leaderboards-v2.sql (it depends on profiles.share_code + country).
-- Additive only: three SECURITY DEFINER functions + grants. No table changes.
--
-- The board ranks on the same points that drive the badge, so the ladder a
-- player already sees on their profile is the ladder they are ranked by. No
-- second scoring system.
--
-- POINTS ARITHMETIC LIVES IN THREE PLACES AND MUST BE CHANGED IN ALL THREE:
--   frontend/src/utils/badges.ts  (POINT_WEIGHTS + aggregateRows) — canonical
--   supabase/badges.sql           (player_points, for explicit user ids)
--   supabase/leaderboards-alltime.sql (this file, for the whole field)
-- No test can catch a drift between them: the SQL needs a database. Grep for
-- POINT_WEIGHTS before touching any weight, and keep the walkover guard
-- (cards_played_total >= 5) identical everywhere.
--
-- Decay is deliberately NOT applied here. The badge decay bleeds the surplus
-- above your current tier so a tier never demotes; that is about progress, not
-- standing. An all-time board is a record of what happened, so an inactive
-- player keeps the rank they earned. "Who is hot right now" is the weekly board.

drop function if exists public.alltime_leaderboard(text, int);

create or replace function public.alltime_leaderboard(
    p_country text default null,
    max_rows int default 100
)
returns table (
    rank bigint,
    user_id uuid,
    username text,
    share_code text,
    country text,
    skin text,
    games bigint,
    wins bigint,
    points bigint,
    is_me boolean
)
language sql
security definer
set search_path = public
stable
as $$
    with scored as (
        select
            gr.user_id,
            coalesce(p.username, 'PLAYER') as username,
            p.share_code,
            p.country,
            p.equipped_card_back as skin,
            count(*) as games,
            count(*) filter (where gr.result = 'won') as wins,
            (
                count(*) filter (where gr.result = 'won' and gr.cards_played_total >= 5) * 100
              + count(*) filter (where gr.result in ('lost', 'eliminated') and gr.cards_played_total >= 5) * 12
              + coalesce(sum(gr.draw_cards_played), 0) * 2
              + coalesce(sum(gr.biggest_stack_survived), 0) * 3
              + coalesce(sum(gr.uno_calls), 0) * 4
              + count(distinct (gr.played_at at time zone 'UTC')::date) * 25
            )::bigint as points
        from game_results gr
        left join profiles p on p.id = gr.user_id
        where p_country is null or p.country = p_country
        group by gr.user_id, p.username, p.share_code, p.country, p.equipped_card_back
    )
    select
        -- Same points, fewer games played is the sharper player.
        row_number() over (order by s.points desc, s.games asc) as rank,
        s.user_id,
        s.username,
        s.share_code,
        s.country,
        s.skin,
        s.games,
        s.wins,
        s.points,
        (auth.uid() is not null and s.user_id = auth.uid()) as is_me
    from scored s
    order by 1
    limit max_rows;
$$;

grant execute on function public.alltime_leaderboard to anon, authenticated;

-- The viewer's own standing, even when they sit far below the visible rows.
-- Ranks against the same slice the board is showing, and returns their own
-- totals so the pinned row is complete without a second query. Signed out,
-- my_rank is null and only total_players is meaningful.

drop function if exists public.alltime_my_rank(text);

create or replace function public.alltime_my_rank(p_country text default null)
returns table (
    my_rank bigint,
    total_players bigint,
    games bigint,
    wins bigint,
    points bigint
)
language sql
security definer
set search_path = public
stable
as $$
    with scored as (
        select
            gr.user_id,
            count(*) as games,
            count(*) filter (where gr.result = 'won') as wins,
            (
                count(*) filter (where gr.result = 'won' and gr.cards_played_total >= 5) * 100
              + count(*) filter (where gr.result in ('lost', 'eliminated') and gr.cards_played_total >= 5) * 12
              + coalesce(sum(gr.draw_cards_played), 0) * 2
              + coalesce(sum(gr.biggest_stack_survived), 0) * 3
              + coalesce(sum(gr.uno_calls), 0) * 4
              + count(distinct (gr.played_at at time zone 'UTC')::date) * 25
            )::bigint as points
        from game_results gr
        left join profiles p on p.id = gr.user_id
        where p_country is null or p.country = p_country
        group by gr.user_id
    ),
    ranked as (
        select user_id, games, wins, points,
               row_number() over (order by points desc, games asc) as rnk
        from scored
    ),
    me as (
        select * from ranked
        where auth.uid() is not null and user_id = auth.uid()
        limit 1
    )
    select
        (select rnk from me),
        (select count(*) from ranked),
        coalesce((select games from me), 0),
        coalesce((select wins from me), 0),
        coalesce((select points from me), 0);
$$;

grant execute on function public.alltime_my_rank to anon, authenticated;

-- Countries that have at least one ranked player, biggest field first. A
-- global top 100 is dead for most players; this is what makes the filter
-- worth opening. Countries with nobody in them are never listed.

drop function if exists public.alltime_countries();

create or replace function public.alltime_countries()
returns table (country text, players bigint)
language sql
security definer
set search_path = public
stable
as $$
    select p.country, count(distinct gr.user_id) as players
    from game_results gr
    join profiles p on p.id = gr.user_id
    where p.country is not null
    group by p.country
    order by players desc, p.country asc;
$$;

grant execute on function public.alltime_countries to anon, authenticated;


-- =====================================================================
-- results-hardening.sql
-- =====================================================================

-- Results and profiles hardening. Run in the Supabase SQL Editor in TWO steps.
--
-- STEP 1 (run now, before the frontend deploy): additive and safe for the
-- live client. Creates the result-recording function, narrows what a player
-- can write on their own profile, and pins three function search paths.
--
-- STEP 2 (run after the frontend that calls record_bot_result is live):
-- removes the direct insert on game_results. Until step 2 the old insert
-- path still works, so an old cached tab keeps logging results.
--
-- Why: a player could POST straight to /rest/v1/game_results with any
-- numbers, backdate played_at, and take #1 on every board and the top badge.
-- The browser still reports its own solo games (there is no server for them),
-- but now through one function that owns user_id, played_at and is_bot_game,
-- clamps every stat to what real games produce, and caps how many results a
-- player can file per 10 minutes so a script can't flood the boards.

-- ============================== STEP 1 ==============================

create or replace function public.record_bot_result(
    p_game_id text,
    p_result text,
    p_opponent_count int,
    p_cards_remaining int,
    p_peak_cards int,
    p_draw_cards_played int,
    p_wild_cards_played int,
    p_cards_played_total int,
    p_skips_dealt int,
    p_swaps_made int,
    p_draws_taken int,
    p_biggest_stack_survived int,
    p_uno_calls int,
    p_uno_penalties int,
    p_game_duration_secs int
)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
    daily_date date;
begin
    if me is null then return 'unauthorized'; end if;
    if p_result not in ('won', 'lost', 'eliminated') then return 'bad_result'; end if;
    if p_game_id !~ '^(bot-[0-9]{10,16}|daily-[0-9]{4}-[0-9]{2}-[0-9]{2})$' then return 'bad_game'; end if;

    -- A daily can only be filed for today, give or take a timezone.
    if p_game_id like 'daily-%' then
        daily_date := substr(p_game_id, 7)::date;
        if daily_date not between (now() at time zone 'utc')::date - 1
                              and (now() at time zone 'utc')::date + 1 then
            return 'bad_game';
        end if;
    end if;

    -- ponytail: at most 40 results per player per 10 minutes. Real players
    -- peak at 36 (99.9th percentile over 30 days); a script is capped at
    -- 4 fake results a minute. Spacing results out instead would drop real
    -- ones: 10% arrive under 10s apart. A replay check of the daily's turn
    -- log is the upgrade if that matters.
    if (
        select count(*) from game_results
        where user_id = me and is_bot_game
          and played_at > now() - interval '10 minutes'
    ) >= 40 then return 'too_soon'; end if;

    -- Ceilings sit well above anything a real game has produced (max seen:
    -- 100 cards played, 25 draw cards, 46-card stack survived).
    insert into game_results (
        game_id, user_id, opponent_count, result, cards_remaining, peak_cards,
        draw_cards_played, wild_cards_played, cards_played_total, skips_dealt,
        swaps_made, draws_taken, biggest_stack_survived, uno_calls,
        uno_penalties, game_duration_secs, is_bot_game, played_at
    ) values (
        p_game_id, me,
        least(greatest(coalesce(p_opponent_count, 1), 1), 9),
        p_result,
        least(greatest(coalesce(p_cards_remaining, 0), 0), 25),
        least(greatest(coalesce(p_peak_cards, 0), 0), 25),
        least(greatest(coalesce(p_draw_cards_played, 0), 0), 60),
        least(greatest(coalesce(p_wild_cards_played, 0), 0), 60),
        least(greatest(coalesce(p_cards_played_total, 0), 0), 200),
        least(greatest(coalesce(p_skips_dealt, 0), 0), 60),
        least(greatest(coalesce(p_swaps_made, 0), 0), 30),
        least(greatest(coalesce(p_draws_taken, 0), 0), 200),
        least(greatest(coalesce(p_biggest_stack_survived, 0), 0), 100),
        least(greatest(coalesce(p_uno_calls, 0), 0), 50),
        least(greatest(coalesce(p_uno_penalties, 0), 0), 20),
        least(greatest(coalesce(p_game_duration_secs, 0), 0), 6 * 3600),
        true, now()
    );
    return 'ok';
exception
    -- The daily's one-attempt unique index.
    when unique_violation then return 'duplicate';
end;
$$;

revoke execute on function public.record_bot_result from public, anon;
grant execute on function public.record_bot_result to authenticated;

-- A player may write only their name, country and card back. share_code,
-- games_played, games_won, last_seen_at and created_at are no longer
-- writable from the browser (last_seen_at goes through touch_presence).
-- id stays in the column list because the client upserts on id; RLS still
-- pins it to auth.uid().
revoke insert, update on public.profiles from anon, authenticated;
grant insert (id, username) on public.profiles to authenticated;
grant update (id, username, country, equipped_card_back) on public.profiles to authenticated;

-- not valid: checks every new write without failing on an old row.
alter table public.profiles drop constraint if exists profiles_username_shape;
alter table public.profiles add constraint profiles_username_shape
    check (char_length(username) between 1 and 40 and username !~ '[[:cntrl:]]') not valid;
alter table public.profiles drop constraint if exists profiles_country_shape;
alter table public.profiles add constraint profiles_country_shape
    check (country is null or country ~ '^[A-Z]{2}$') not valid;
alter table public.profiles drop constraint if exists profiles_card_back_shape;
alter table public.profiles add constraint profiles_card_back_shape
    check (equipped_card_back is null or char_length(equipped_card_back) <= 32) not valid;

-- Database linter: search_path was not pinned on these three.
-- They belong to the retired Supabase-broadcast multiplayer path and do not
-- exist in a fresh project, so each is pinned only if it is present.
do $$
begin
    if to_regprocedure('public.commit_move(uuid, integer, jsonb, jsonb)') is not null then
        alter function public.commit_move(uuid, integer, jsonb, jsonb) set search_path = public, pg_temp;
    end if;
    if to_regprocedure('public.generate_room_code()') is not null then
        alter function public.generate_room_code() set search_path = public, pg_temp;
    end if;
    if to_regprocedure('public.update_updated_at()') is not null then
        alter function public.update_updated_at() set search_path = public, pg_temp;
    end if;
end $$;

-- A trigger function; nobody should be able to call it over the API.
revoke execute on function public.create_profile_for_user() from public, anon, authenticated;

-- ============================== STEP 2 ==============================
-- Run after the frontend that calls record_bot_result has deployed.
--
-- revoke insert on public.game_results from anon, authenticated;
-- drop policy if exists "Users can insert own results" on public.game_results;
-- drop policy if exists game_results_insert_own on public.game_results;  -- name used by 00-base-schema.sql


-- =====================================================================
-- ranks.sql
-- =====================================================================

-- Public rank lookup for visible seats (waiting room, game over).
-- Run in the Supabase SQL Editor. Additive only: one SECURITY DEFINER
-- function + grant. game_results RLS is owner-select-only, so showing an
-- opponent's rank needs a definer read. Exposes nothing but win counts for
-- explicitly requested user ids.

create or replace function public.player_ranks(ids uuid[])
returns table (user_id uuid, wins bigint)
language sql
security definer
set search_path = public
stable
as $$
    select gr.user_id, count(*) filter (where gr.result = 'won') as wins
    from game_results gr
    where gr.user_id = any(ids)
    group by gr.user_id;
$$;

grant execute on function public.player_ranks to anon, authenticated;


-- =====================================================================
-- profile-pages.sql
-- =====================================================================

-- Public profile pages (/p/<share_code>). Run in the Supabase SQL Editor
-- AFTER leaderboards-v2.sql (it depends on profiles.share_code + country).
-- Additive only: two SECURITY DEFINER functions + grants. No table changes.
--
-- game_results RLS is owner-select-only; a public profile exposes ONE row of
-- aggregates (never row-level history) plus a 10-game W/L form strip. It also
-- returns user_id so the client can look up the profile's badge via
-- player_points (badges.sql); re-run this (drop + recreate) to pick that up.

drop function if exists public.public_profile(text);

create or replace function public.public_profile(p_share_code text)
returns table (
    user_id uuid,
    username text,
    country text,
    skin text,
    member_since timestamptz,
    games bigint,
    wins bigint,
    best_win_streak bigint,
    max_stack_survived int,
    max_peak_cards int,
    max_peak_cards_won int,
    min_cards_won int,
    min_duration_won int,
    max_duration int,
    sum_skips bigint,
    sum_draw_cards bigint,
    sum_wild_cards bigint,
    sum_uno_calls bigint,
    sum_swaps bigint,
    daily_played bigint,
    recent_form text[]
)
language sql
security definer
set search_path = public
stable
as $$
    with target as (
        select id, username, country, equipped_card_back, created_at
        from profiles
        where share_code = p_share_code
    ),
    results as (
        select gr.*
        from game_results gr
        join target t on gr.user_id = t.id
    ),
    streaks as (
        -- gaps-and-islands: consecutive wins share the same (rn - rn_within_wins)
        select coalesce(max(len), 0) as best
        from (
            select count(*) as len
            from (
                select row_number() over (order by played_at)
                     - row_number() over (partition by (result = 'won') order by played_at) as grp,
                       result
                from results
            ) marked
            where result = 'won'
            group by grp
        ) islands
    ),
    form as (
        select coalesce(array_agg(result order by played_at desc), '{}') as recent
        from (
            select result, played_at from results
            order by played_at desc
            limit 10
        ) last10
    )
    select
        t.id as user_id,
        t.username,
        t.country,
        t.equipped_card_back as skin,
        t.created_at as member_since,
        count(r.*) as games,
        count(*) filter (where r.result = 'won') as wins,
        (select best from streaks) as best_win_streak,
        coalesce(max(r.biggest_stack_survived), 0) as max_stack_survived,
        coalesce(max(r.peak_cards), 0) as max_peak_cards,
        coalesce(max(r.peak_cards) filter (where r.result = 'won'), 0) as max_peak_cards_won,
        -- Speed/efficiency records require >= 5 cards actually played:
        -- walkover wins (every opponent left) record near-zero plays and
        -- seconds-long durations that aren't real records.
        min(r.cards_played_total) filter (where r.result = 'won' and r.cards_played_total >= 5) as min_cards_won,
        min(r.game_duration_secs) filter (where r.result = 'won' and r.game_duration_secs > 0 and r.cards_played_total >= 5) as min_duration_won,
        coalesce(max(r.game_duration_secs), 0) as max_duration,
        coalesce(sum(r.skips_dealt), 0) as sum_skips,
        coalesce(sum(r.draw_cards_played), 0) as sum_draw_cards,
        coalesce(sum(r.wild_cards_played), 0) as sum_wild_cards,
        coalesce(sum(r.uno_calls), 0) as sum_uno_calls,
        coalesce(sum(r.swaps_made), 0) as sum_swaps,
        count(*) filter (where r.game_id like 'daily-%') as daily_played,
        (select recent from form) as recent_form
    from target t
    left join results r on true
    group by t.id, t.username, t.country, t.equipped_card_back, t.created_at;
$$;

grant execute on function public.public_profile to anon, authenticated;

-- Weekly spotlight cards for the leaderboard page: three different skill
-- archetypes get famous each week, not just the win grinders.

create or replace function public.weekly_spotlights()
returns table (
    kind text,
    username text,
    share_code text,
    country text,
    value bigint
)
language sql
security definer
set search_path = public
stable
as $$
    (
        select 'fastest_win' as kind,
               coalesce(p.username, 'PLAYER'), p.share_code, p.country,
               gr.game_duration_secs::bigint as value
        from game_results gr
        left join profiles p on p.id = gr.user_id
        where gr.played_at > now() - interval '7 days'
          and gr.result = 'won' and gr.game_duration_secs > 0
          -- exclude walkover wins (opponents left, near-zero cards played)
          and gr.cards_played_total >= 5
        order by gr.game_duration_secs asc
        limit 1
    )
    union all
    (
        select 'biggest_stack',
               coalesce(p.username, 'PLAYER'), p.share_code, p.country,
               gr.biggest_stack_survived::bigint
        from game_results gr
        left join profiles p on p.id = gr.user_id
        where gr.played_at > now() - interval '7 days'
          and gr.biggest_stack_survived > 0
        order by gr.biggest_stack_survived desc
        limit 1
    )
    union all
    (
        select 'most_wins',
               coalesce(p.username, 'PLAYER'), p.share_code, p.country,
               count(*) filter (where gr.result = 'won')::bigint
        from game_results gr
        left join profiles p on p.id = gr.user_id
        where gr.played_at > now() - interval '7 days'
        group by gr.user_id, p.username, p.share_code, p.country
        having count(*) filter (where gr.result = 'won') > 0
        order by 5 desc
        limit 1
    );
$$;

grant execute on function public.weekly_spotlights to anon, authenticated;


-- =====================================================================
-- profile-activity.sql
-- =====================================================================

-- Daily activity grid for public profiles (GitHub-contribution-style heatmap).
-- Run in the Supabase SQL Editor AFTER leaderboards-v2.sql (needs
-- profiles.share_code). Additive only: one SECURITY DEFINER function + grant.
--
-- Exposes per-DAY aggregates only (games + wins), never row-level history —
-- same privacy posture as public_profile.
--
-- p_tz is an IANA timezone name from the browser (Intl resolvedOptions), so
-- "a day" matches the viewer's calendar. An invalid name makes the function
-- error; the frontend treats any error as feature-not-available and hides
-- the heatmap.

create or replace function public.profile_activity(p_share_code text, p_tz text default 'UTC')
returns table (day date, games bigint, wins bigint)
language sql
security definer
set search_path = public
stable
as $$
    select (gr.played_at at time zone p_tz)::date as day,
           count(*) as games,
           count(*) filter (where gr.result = 'won') as wins
    from game_results gr
    join profiles p on p.id = gr.user_id
    where p.share_code = p_share_code
      and gr.played_at > now() - interval '190 days'
    group by 1
    order by 1;
$$;

grant execute on function public.profile_activity to anon, authenticated;


-- =====================================================================
-- profile-dossier.sql
-- =====================================================================

-- Dossier sections for the public profile page (/p/<share_code>). Run in the
-- Supabase SQL Editor AFTER profile-pages.sql and leaderboards-alltime.sql
-- (this depends on profiles.share_code + country). Additive only: three
-- SECURITY DEFINER functions + grants. No table changes.
--
-- public_profile() returns one row of aggregates, which is enough for the
-- badge and the personal bests but cannot answer two things the dossier shows:
-- where a player stands in the field, and when they took each badge. Both need
-- data that owner-only RLS keeps out of the client, so both are computed here
-- and returned already reduced.
--
-- POINTS ARITHMETIC LIVES IN FOUR PLACES AND MUST BE CHANGED IN ALL FOUR:
--   frontend/src/utils/badges.ts       (POINT_WEIGHTS + aggregateRows) — canonical
--   supabase/badges.sql                (player_points, for explicit user ids)
--   supabase/leaderboards-alltime.sql  (the whole field)
--   supabase/profile-dossier.sql       (this file)
-- No test can catch a drift between them: the SQL needs a database. Grep for
-- POINT_WEIGHTS before touching any weight, and keep the walkover guard
-- (cards_played_total >= 5) identical everywhere.
--
-- profile_promotions ALSO duplicates the tier thresholds from badges.ts BADGES.
-- That is the only copy of the ladder outside TypeScript. Change both together.
--
-- EXPOSURE NOTE: profile_recent_games widens what a public profile shows from a
-- W/L form strip to the last N games in detail. It is deliberately bounded, and
-- returns no game_id and no user_id — only what the activity row renders. If a
-- private-profile setting ever ships, this is the function it has to gate.

-- ---------------------------------------------------------------------------
-- Where this player stands, globally and in their own country.
-- alltime_my_rank answers this for the CALLER via auth.uid(); a profile page is
-- about somebody else, so the target comes from the share code instead.
--
-- KNOWN COST, accepted deliberately (2026-08-29): this aggregates the whole of
-- game_results on every call. Measured at 32,912 rows / 3,308 scored players:
--
--   GroupAggregate (actual rows=3308) <- Incremental Sort (actual rows=32912)
--   Execution Time: 449.344 ms
--
-- The ranking itself is free; the aggregate is the whole cost, and it grows
-- with total games played rather than with users. alltime_leaderboard and
-- alltime_my_rank pay the identical cost, so the site pays it three ways.
--
-- The fix, when it starts to hurt: one materialised view of the scored set
-- (user_id, country, games, points), refreshed on a schedule, with all three
-- functions reading from it — profile rank becomes a lookup plus a ranking over
-- ~3k rows. pg_cron 1.6.4 is available on the project but not installed. The
-- trade is staleness bounded by the refresh interval, which an all-time board
-- can absorb: it already ignores decay for the same "record of what happened"
-- reason. A trigger-maintained table is the other option and is rejected here,
-- because it would put the points arithmetic in a fifth place.
-- ---------------------------------------------------------------------------

drop function if exists public.profile_rank(text);

create or replace function public.profile_rank(p_share_code text)
returns table (
    global_rank bigint,
    global_total bigint,
    country_rank bigint,
    country_total bigint
)
language sql
security definer
set search_path = public
stable
as $$
    with target as (
        select id, country from profiles where share_code = p_share_code
    ),
    scored as (
        select
            gr.user_id,
            p.country,
            count(*) as games,
            (
                count(*) filter (where gr.result = 'won' and gr.cards_played_total >= 5) * 100
              + count(*) filter (where gr.result in ('lost', 'eliminated') and gr.cards_played_total >= 5) * 12
              + coalesce(sum(gr.draw_cards_played), 0) * 2
              + coalesce(sum(gr.biggest_stack_survived), 0) * 3
              + coalesce(sum(gr.uno_calls), 0) * 4
              + count(distinct (gr.played_at at time zone 'UTC')::date) * 25
            )::bigint as points
        from game_results gr
        left join profiles p on p.id = gr.user_id
        group by gr.user_id, p.country
    ),
    global_ranked as (
        select user_id, row_number() over (order by points desc, games asc) as rnk
        from scored
    ),
    country_ranked as (
        select s.user_id, row_number() over (order by s.points desc, s.games asc) as rnk
        from scored s
        join target t on t.country is not null and s.country = t.country
    )
    select
        (select g.rnk from global_ranked g join target t on g.user_id = t.id),
        (select count(*) from scored),
        (select c.rnk from country_ranked c join target t on c.user_id = t.id),
        (select count(*) from country_ranked);
$$;

grant execute on function public.profile_rank to anon, authenticated;

-- ---------------------------------------------------------------------------
-- When this player took each badge.
--
-- Derived, never stored: the points formula is replayed over their games in
-- order, and the first game whose running total reaches a threshold is the game
-- that bought that tier. Mirrors frontend/src/utils/promotions.ts, which does
-- the same replay client-side for the signed-in owner (who already holds their
-- own rows and needs no round trip).
--
-- Every term of the sum is non-negative, so the running total only ever grows
-- and the earliest crossing really is the promotion. The distinct-day term is a
-- running count of first-games-of-a-date rather than a plain sum.
-- ---------------------------------------------------------------------------

drop function if exists public.profile_promotions(text);

create or replace function public.profile_promotions(p_share_code text)
returns table (
    tier int,
    threshold bigint,
    at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    with target as (
        select id from profiles where share_code = p_share_code
    ),
    ordered as (
        select
            gr.played_at,
            gr.result,
            gr.cards_played_total,
            gr.draw_cards_played,
            gr.biggest_stack_survived,
            gr.uno_calls,
            case
                when row_number() over (
                    partition by (gr.played_at at time zone 'UTC')::date
                    order by gr.played_at
                ) = 1 then 1 else 0
            end as new_day
        from game_results gr
        join target t on gr.user_id = t.id
    ),
    running as (
        select
            played_at,
            (
                sum(case when result = 'won' and cards_played_total >= 5 then 1 else 0 end) over w * 100
              + sum(case when result in ('lost', 'eliminated') and cards_played_total >= 5 then 1 else 0 end) over w * 12
              + sum(draw_cards_played) over w * 2
              + sum(biggest_stack_survived) over w * 3
              + sum(uno_calls) over w * 4
              + sum(new_day) over w * 25
            )::bigint as points
        from ordered
        window w as (order by played_at rows between unbounded preceding and current row)
    ),
    tiers (tier, threshold) as (
        values (1, 0::bigint), (2, 250::bigint), (3, 600::bigint), (4, 1300::bigint),
               (5, 2700::bigint), (6, 5500::bigint), (7, 11000::bigint),
               (8, 22000::bigint), (9, 45000::bigint), (10, 100000::bigint),
               (11, 140000::bigint), (12, 196000::bigint), (13, 274000::bigint),
               (14, 384000::bigint), (15, 538000::bigint), (16, 753000::bigint),
               (17, 1050000::bigint), (18, 1480000::bigint), (19, 2070000::bigint),
               (20, 2890000::bigint)
    )
    select ti.tier, ti.threshold, min(r.played_at)
    from tiers ti
    join running r on r.points >= ti.threshold
    group by ti.tier, ti.threshold
    order by ti.tier;
$$;

grant execute on function public.profile_promotions to anon, authenticated;

-- ---------------------------------------------------------------------------
-- The last few games, with what each one was worth.
--
-- Bounded and reduced: no game_id, no user_id, no opponent identities. `points`
-- is the same per-game contribution the post-game badge check uses, so the
-- number on a profile row matches the one the player saw when the game ended.
-- The day bonus is excluded, exactly as gameContribution excludes it — a single
-- game cannot know whether it was the first of its day.
-- ---------------------------------------------------------------------------

drop function if exists public.profile_recent_games(text, int);

create or replace function public.profile_recent_games(
    p_share_code text,
    max_rows int default 10
)
returns table (
    played_at timestamptz,
    result text,
    is_bot_game boolean,
    opponent_count int,
    cards_played_total int,
    cards_remaining int,
    peak_cards int,
    biggest_stack_survived int,
    points int
)
language sql
security definer
set search_path = public
stable
as $$
    select
        gr.played_at,
        gr.result::text,
        gr.is_bot_game,
        gr.opponent_count,
        gr.cards_played_total,
        gr.cards_remaining,
        gr.peak_cards,
        gr.biggest_stack_survived,
        (
            case
                when gr.cards_played_total >= 5 and gr.result = 'won' then 100
                when gr.cards_played_total >= 5 and gr.result in ('lost', 'eliminated') then 12
                else 0
            end
          + greatest(coalesce(gr.draw_cards_played, 0), 0) * 2
          + greatest(coalesce(gr.biggest_stack_survived, 0), 0) * 3
          + greatest(coalesce(gr.uno_calls, 0), 0) * 4
        )::int as points
    from game_results gr
    join profiles p on p.id = gr.user_id
    where p.share_code = p_share_code
    order by gr.played_at desc
    limit greatest(1, least(coalesce(max_rows, 10), 50));
$$;

grant execute on function public.profile_recent_games to anon, authenticated;


-- =====================================================================
-- badges.sql
-- =====================================================================

-- Public points lookup for visible seats (waiting room, game over, every
-- in-game opponent). Run in the Supabase SQL Editor. Additive only: one
-- SECURITY DEFINER function + grant. game_results RLS is owner-select-only,
-- so showing an opponent's badge needs a definer read. Exposes nothing but
-- the computed points and days-idle for explicitly requested user ids.
--
-- Mirrors the weighted sum in frontend/src/utils/badges.ts (POINT_WEIGHTS +
-- aggregateRows). The floored inactivity decay is applied client-side
-- (applyDecay) from `days_idle`, so the tier table lives in one place (TS).
-- Keep the weights and the walkover guard (cards_played_total >= 5) in sync.
-- The same arithmetic runs a third time in supabase/leaderboards-alltime.sql,
-- which ranks the whole field instead of explicit ids. Change all three.

create or replace function public.player_points(ids uuid[])
returns table (user_id uuid, points bigint, days_idle int)
language sql
security definer
set search_path = public
stable
as $$
    select
        gr.user_id,
        (
            count(*) filter (where gr.result = 'won' and gr.cards_played_total >= 5) * 100
          + count(*) filter (where gr.result in ('lost', 'eliminated') and gr.cards_played_total >= 5) * 12
          + coalesce(sum(gr.draw_cards_played), 0) * 2
          + coalesce(sum(gr.biggest_stack_survived), 0) * 3
          + coalesce(sum(gr.uno_calls), 0) * 4
          + count(distinct (gr.played_at at time zone 'UTC')::date) * 25
        )::bigint as points,
        greatest(0, extract(day from (now() - max(gr.played_at)))::int) as days_idle
    from game_results gr
    where gr.user_id = any(ids)
    group by gr.user_id;
$$;

grant execute on function public.player_points to anon, authenticated;


-- =====================================================================
-- badges-prestige.sql
-- =====================================================================

-- Ranks 11-20 for the public profile's promotion timeline. Run in the
-- Supabase SQL Editor AFTER profile-dossier.sql. Re-runnable: it only
-- replaces profile_promotions, whose ladder must match badges.ts BADGES
-- (profile-dossier.sql carries the same rows for a fresh install).

create or replace function public.profile_promotions(p_share_code text)
returns table (
    tier int,
    threshold bigint,
    at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    with target as (
        select id from profiles where share_code = p_share_code
    ),
    ordered as (
        select
            gr.played_at,
            gr.result,
            gr.cards_played_total,
            gr.draw_cards_played,
            gr.biggest_stack_survived,
            gr.uno_calls,
            case
                when row_number() over (
                    partition by (gr.played_at at time zone 'UTC')::date
                    order by gr.played_at
                ) = 1 then 1 else 0
            end as new_day
        from game_results gr
        join target t on gr.user_id = t.id
    ),
    running as (
        select
            played_at,
            (
                sum(case when result = 'won' and cards_played_total >= 5 then 1 else 0 end) over w * 100
              + sum(case when result in ('lost', 'eliminated') and cards_played_total >= 5 then 1 else 0 end) over w * 12
              + sum(draw_cards_played) over w * 2
              + sum(biggest_stack_survived) over w * 3
              + sum(uno_calls) over w * 4
              + sum(new_day) over w * 25
            )::bigint as points
        from ordered
        window w as (order by played_at rows between unbounded preceding and current row)
    ),
    tiers (tier, threshold) as (
        values (1, 0::bigint), (2, 250::bigint), (3, 600::bigint), (4, 1300::bigint),
               (5, 2700::bigint), (6, 5500::bigint), (7, 11000::bigint),
               (8, 22000::bigint), (9, 45000::bigint), (10, 100000::bigint),
               (11, 140000::bigint), (12, 196000::bigint), (13, 274000::bigint),
               (14, 384000::bigint), (15, 538000::bigint), (16, 753000::bigint),
               (17, 1050000::bigint), (18, 1480000::bigint), (19, 2070000::bigint),
               (20, 2890000::bigint)
    )
