    order by ti.tier;
$$;

grant execute on function public.profile_promotions to anon, authenticated;


-- =====================================================================
-- friends.sql
-- =====================================================================

-- Friends. Run in the Supabase SQL Editor AFTER presence.sql (my_friends
-- returns last_seen_at). Additive: one table, five SECURITY DEFINER
-- functions, grants. Re-running the whole file is safe.
--
-- One row per pair, whichever way round the request went. The unique index on
-- (least, greatest) is what enforces that: without it A -> B and B -> A can
-- both exist, and "are we friends?" stops having one answer.
--
-- RLS is on and the table has no policies, so no client can read or write it
-- directly. Every path goes through the functions below, which is the only
-- place a rate limit or a block check can actually live.
--
-- On the revokes below: a new function is granted EXECUTE to PUBLIC by
-- Postgres and to anon by the project's default privileges, so both have to
-- be named. Revoking PUBLIC alone leaves anon holding its own grant - the
-- state this project was briefly in, where an unauthenticated caller could
-- still reach every function.
--
-- The auth.uid() check at the top of each body is the belt to that pair of
-- braces: even when a call gets through, it returns 'unauthorized', reads
-- nothing and writes nothing.

create table if not exists friendships (
    requester_id uuid not null references auth.users(id) on delete cascade,
    addressee_id uuid not null references auth.users(id) on delete cascade,
    status text not null check (status in ('pending', 'accepted', 'blocked', 'declined')),
    -- Who pressed block. Null unless status is 'blocked'; without it the row
    -- cannot say which side is unwelcome.
    blocked_by uuid references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    responded_at timestamptz,
    primary key (requester_id, addressee_id)
);

create unique index if not exists friendships_pair_idx
    on friendships (least(requester_id, addressee_id), greatest(requester_id, addressee_id));

create index if not exists friendships_addressee_idx on friendships (addressee_id, status);

-- Idempotent, so a database that ran an earlier copy of this file picks up
-- 'declined' instead of failing every refusal on the old check.
alter table friendships drop constraint if exists friendships_status_check;
alter table friendships add constraint friendships_status_check
    check (status in ('pending', 'accepted', 'blocked', 'declined'));

alter table friendships enable row level security;

-- --- Writes -----------------------------------------------------------------

-- Ask to be friends. Returns one of: sent, accepted, already, blocked, self,
-- rate_limited. A request to someone who already asked you accepts theirs -
-- two people pressing ADD at the same time should end as friends, not as two
-- pending rows nobody can resolve.

create or replace function public.send_friend_request(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
    existing friendships%rowtype;
    sent_today int;
begin
    if me is null then return 'unauthorized'; end if;
    if p_user is null or p_user = me then return 'self'; end if;

    if not exists (select 1 from profiles where id = p_user) then return 'not_found'; end if;

    select * into existing from friendships
    where least(requester_id, addressee_id) = least(me, p_user)
      and greatest(requester_id, addressee_id) = greatest(me, p_user);

    -- Tested on the row, not on FOUND: FOUND belongs to the last statement
    -- that set it, and anything added above this line would silently move it.
    if existing.requester_id is not null then
        if existing.status = 'blocked' then return 'blocked'; end if;
        if existing.status = 'accepted' then return 'already'; end if;
        if existing.status = 'declined' then
            -- A refusal holds for a week. Long enough that DECLINE means
            -- something, short enough that it is not a life sentence.
            if existing.responded_at > now() - interval '7 days' then return 'declined'; end if;
            update friendships
            set requester_id = me, addressee_id = p_user, status = 'pending',
                created_at = now(), responded_at = null
            where requester_id = existing.requester_id and addressee_id = existing.addressee_id;
            return 'sent';
        end if;
        -- Pending: theirs to me becomes friendship, mine to them stays put.
        if existing.addressee_id = me then
            update friendships set status = 'accepted', responded_at = now()
            where requester_id = existing.requester_id and addressee_id = existing.addressee_id;
            return 'accepted';
        end if;
        return 'already';
    end if;

    -- A cap on strangers asked per day. The number is deliberately generous:
    -- it is here to stop a script, not a sociable player.
    --
    -- Declined rows count. They used to be deleted, which meant a burst of
    -- refusals handed the sender their slots straight back - the cap only
    -- ever bit someone nobody had answered yet.
    select count(*) into sent_today from friendships
    where requester_id = me and created_at > now() - interval '24 hours';
    if sent_today >= 20 then return 'rate_limited'; end if;

    insert into friendships (requester_id, addressee_id, status)
    values (me, p_user, 'pending');
    return 'sent';
end;
$$;

revoke execute on function public.send_friend_request(uuid) from public, anon;
grant execute on function public.send_friend_request(uuid) to authenticated;

-- Answer a request addressed to me. Declining keeps the row as 'declined'
-- rather than deleting it: a deleted refusal let the same person ask again
-- immediately, and handed their daily cap a free slot. The refusal expires
-- after a week in send_friend_request, so it bounds a pest without being a
-- permanent grudge.

create or replace function public.respond_friend_request(p_user uuid, p_accept boolean)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;

    if p_accept then
        update friendships set status = 'accepted', responded_at = now()
        where requester_id = p_user and addressee_id = me and status = 'pending';
        if not found then return 'not_found'; end if;
        return 'accepted';
    end if;

    update friendships set status = 'declined', responded_at = now()
    where requester_id = p_user and addressee_id = me and status = 'pending';
    if not found then return 'not_found'; end if;
    return 'declined';
end;
$$;

revoke execute on function public.respond_friend_request(uuid, boolean) from public, anon;
grant execute on function public.respond_friend_request(uuid, boolean) to authenticated;

-- Block. Overwrites whatever the pair had, including an accepted friendship,
-- and send_friend_request refuses both directions afterwards.

create or replace function public.block_player(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;
    if p_user is null or p_user = me then return 'self'; end if;

    delete from friendships
    where least(requester_id, addressee_id) = least(me, p_user)
      and greatest(requester_id, addressee_id) = greatest(me, p_user);

    insert into friendships (requester_id, addressee_id, status, blocked_by, responded_at)
    values (me, p_user, 'blocked', me, now());
    return 'blocked';
end;
$$;

revoke execute on function public.block_player(uuid) from public, anon;
grant execute on function public.block_player(uuid) to authenticated;

-- Undo my own block. A block placed by the other side stays.

create or replace function public.unblock_player(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;

    delete from friendships
    where status = 'blocked' and blocked_by = me
      and least(requester_id, addressee_id) = least(me, p_user)
      and greatest(requester_id, addressee_id) = greatest(me, p_user);
    if not found then return 'not_found'; end if;
    return 'unblocked';
end;
$$;

revoke execute on function public.unblock_player(uuid) from public, anon;
grant execute on function public.unblock_player(uuid) to authenticated;

-- --- Read -------------------------------------------------------------------

-- Everyone connected to me, in one round trip: accepted friends, requests in
-- both directions, and the people I have blocked. `incoming` is what the UI
-- needs to tell "they asked you" from "you asked them"; a block placed by the
-- other side is not returned at all, because there is nothing to act on.

create or replace function public.my_friends()
returns table (
    user_id uuid,
    username text,
    share_code text,
    skin text,
    last_seen_at timestamptz,
    status text,
    incoming boolean,
    created_at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    select
        p.id,
        p.username,
        p.share_code,
        p.equipped_card_back,
        p.last_seen_at,
        f.status,
        f.addressee_id = auth.uid(),
        f.created_at
    from friendships f
    join profiles p
      on p.id = case when f.requester_id = auth.uid() then f.addressee_id else f.requester_id end
    where (f.requester_id = auth.uid() or f.addressee_id = auth.uid())
      and f.status <> 'declined'
      and (f.status <> 'blocked' or f.blocked_by = auth.uid())
    order by f.created_at desc
$$;

revoke execute on function public.my_friends() from public, anon;
grant execute on function public.my_friends() to authenticated;

-- --- Removing a friend ------------------------------------------------------

-- Unfriend. Blocking was the only exit, and it is a much heavier hammer than
-- "we do not play any more" - it stops invites and requests in both
-- directions, permanently, and reads as an accusation. This just deletes the
-- pair row, so either side can ask again later.
--
-- Deliberately covers a pending request too: withdrawing one you sent should
-- not require the other person to answer it first.

create or replace function public.remove_friend(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;

    delete from friendships
    where status in ('accepted', 'pending')
      and least(requester_id, addressee_id) = least(me, p_user)
      and greatest(requester_id, addressee_id) = greatest(me, p_user);
    if not found then return 'not_found'; end if;
    return 'removed';
end;
$$;

revoke execute on function public.remove_friend(uuid) from public, anon;
grant execute on function public.remove_friend(uuid) to authenticated;


-- =====================================================================
-- friends-realtime.sql
-- =====================================================================

-- Live friend requests. Run in the Supabase SQL Editor AFTER friends.sql.
-- Additive: one policy, one publication change. Re-runnable.
--
-- Realtime delivers postgres_changes through RLS, so a row nobody may SELECT
-- never reaches a subscriber - which is why friend requests only ever showed
-- up on a lobby reload. The client treats each event as a nudge to call
-- my_friends again; the payload itself is not rendered.
--
-- The policy is deliberately narrow: exactly the two rows the live surfaces
-- need, nothing else.
--   * a pending request addressed to me (the request toast)
--   * a request I sent, once it is accepted (the "accepted" toast)
-- A declined row stays invisible to its sender, so a refusal is silent, and a
-- blocked row is invisible to both sides, so blocked_by never leaks. Writes
-- still have no policy: they go through the SECURITY DEFINER functions.

drop policy if exists friendships_read_live on friendships;
create policy friendships_read_live on friendships
    for select using (
        (addressee_id = auth.uid() and status = 'pending')
        or (requester_id = auth.uid() and status = 'accepted')
    );

-- Adding a table twice raises, so the guard keeps this file re-runnable.
do $$
begin
    alter publication supabase_realtime add table friendships;
exception when duplicate_object then null;
end;
$$;


-- =====================================================================
-- friends-ping.sql
-- =====================================================================

-- Pings: "I want to play" to a friend who is not online right now.
-- Run in the Supabase SQL Editor AFTER friends.sql. Additive: one table, one
-- policy, three SECURITY DEFINER functions, one publication change.
-- Re-runnable.
--
-- A room invite is useless to someone offline: it lives ten minutes and points
-- at a room that will be gone. A ping carries no room. It says who wants to
-- play, and the receiver answers it whenever they come back by opening a room
-- of their own and inviting the pinger.
--
-- Same shape as room_invites: the receiver can read their own rows so
-- Realtime can deliver them, and writes go only through send_ping, where the
-- limits live. Friends only - unlike invites, a ping reaches someone who is
-- not looking at the game, so it must come from someone they chose.

create table if not exists pings (
    id uuid primary key default gen_random_uuid(),
    from_user uuid not null references auth.users(id) on delete cascade,
    to_user uuid not null references auth.users(id) on delete cascade,
    created_at timestamptz not null default now(),
    -- Set when the receiver answers or waves it away.
    seen_at timestamptz
);

create index if not exists pings_to_idx on pings (to_user, created_at desc);
create index if not exists pings_from_idx on pings (from_user, created_at desc);

alter table pings enable row level security;

drop policy if exists pings_read_own on pings;
create policy pings_read_own on pings
    for select using (to_user = auth.uid());

do $$
begin
    alter publication supabase_realtime add table pings;
exception when duplicate_object then null;
end;
$$;

-- --- Write ------------------------------------------------------------------

-- Returns: sent, self, not_friends, too_soon, rate_limited, unauthorized.

create or replace function public.send_ping(p_user uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
    today int;
begin
    if me is null then return 'unauthorized'; end if;
    if p_user is null or p_user = me then return 'self'; end if;

    if not exists (
        select 1 from friendships
        where status = 'accepted'
          and least(requester_id, addressee_id) = least(me, p_user)
          and greatest(requester_id, addressee_id) = greatest(me, p_user)
    ) then return 'not_friends'; end if;

    -- One per friend per six hours: enough to say "I'm around tonight",
    -- not enough to nag.
    if exists (
        select 1 from pings
        where from_user = me and to_user = p_user
          and created_at > now() - interval '6 hours'
    ) then return 'too_soon'; end if;

    select count(*) into today from pings
    where from_user = me and created_at > now() - interval '1 day';
    if today >= 10 then return 'rate_limited'; end if;

    -- Nothing reads a ping older than a day.
    delete from pings where created_at < now() - interval '2 days';

    insert into pings (from_user, to_user) values (me, p_user);
    return 'sent';
end;
$$;

revoke execute on function public.send_ping(uuid) from public, anon;
grant execute on function public.send_ping(uuid) to authenticated;

-- --- Reads ------------------------------------------------------------------

-- Pings worth answering: mine, unanswered, from someone who is still a
-- friend, and from today. Yesterday's "want to play?" is not an offer any
-- more.

create or replace function public.my_pings()
returns table (
    id uuid,
    from_user uuid,
    from_username text,
    created_at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    select g.id, g.from_user, p.username, g.created_at
    from pings g
    join profiles p on p.id = g.from_user
    where g.to_user = auth.uid()
      and g.seen_at is null
      and g.created_at > now() - interval '1 day'
      and exists (
        select 1 from friendships f
        where f.status = 'accepted'
          and least(f.requester_id, f.addressee_id) = least(g.from_user, g.to_user)
          and greatest(f.requester_id, f.addressee_id) = greatest(g.from_user, g.to_user)
      )
    order by g.created_at desc
$$;

revoke execute on function public.my_pings() from public, anon;
grant execute on function public.my_pings() to authenticated;

-- Who I pinged in the last six hours, so the button can say "Pinged" and
-- stay honest after a reload.

create or replace function public.my_sent_pings()
returns table (to_user uuid, created_at timestamptz)
language sql
security definer
set search_path = public
stable
as $$
    select distinct on (g.to_user) g.to_user, g.created_at
    from pings g
    where g.from_user = auth.uid()
      and g.created_at > now() - interval '6 hours'
    order by g.to_user, g.created_at desc
$$;

revoke execute on function public.my_sent_pings() from public, anon;
grant execute on function public.my_sent_pings() to authenticated;

create or replace function public.dismiss_ping(p_id uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;
    update pings set seen_at = now()
    where id = p_id and to_user = me and seen_at is null;
    if not found then return 'not_found'; end if;
    return 'dismissed';
end;
$$;

revoke execute on function public.dismiss_ping(uuid) from public, anon;
grant execute on function public.dismiss_ping(uuid) to authenticated;


-- =====================================================================
-- friends-recent.sql
-- =====================================================================

-- Played recently: the people a friend request is most likely to land with.
-- Run in the Supabase SQL Editor AFTER friends.sql and presence.sql.
-- Additive: one index, one SECURITY DEFINER read. Re-runnable.
--
-- Multiplayer results share a game_id across the table, so the people you
-- played are the other user_ids on your game_ids. Bot games are skipped (no
-- one to add), and so is anyone you already have a friendships row with in
-- either direction - friend, pending, declined or blocked - so the list never
-- offers ADD to someone it should not.
--
-- game_results is owner-select-only (CLAUDE.md), which is why this is a
-- definer function rather than a client query: it reads other players' rows
-- for the shared games and returns only names and a head-to-head count.

-- The join below looks up every player of each of your games by game_id, and
-- game_results had no index on it (user_id only), so each call scanned the
-- whole table.
create index if not exists game_results_game_id_idx on game_results (game_id);

create or replace function public.recent_opponents()
returns table (
    user_id uuid,
    username text,
    share_code text,
    last_seen_at timestamptz,
    games int,
    my_wins int,
    their_wins int,
    last_played timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    with mine as (
        select game_id, result
        from game_results
        where user_id = auth.uid()
          and not is_bot_game
          and played_at > now() - interval '7 days'
    ),
    them as (
        select g.user_id, g.result as their_result, m.result as my_result, g.played_at
        from game_results g
        join mine m on m.game_id = g.game_id
        where g.user_id <> auth.uid()
          and not g.is_bot_game
    )
    select
        t.user_id,
        p.username,
        p.share_code,
        p.last_seen_at,
        count(*)::int as games,
        count(*) filter (where t.my_result = 'won')::int as my_wins,
        count(*) filter (where t.their_result = 'won')::int as their_wins,
        max(t.played_at) as last_played
    from them t
    join profiles p on p.id = t.user_id
    where not exists (
        select 1 from friendships f
        where (f.requester_id = auth.uid() and f.addressee_id = t.user_id)
           or (f.requester_id = t.user_id and f.addressee_id = auth.uid())
    )
    group by t.user_id, p.username, p.share_code, p.last_seen_at
    order by max(t.played_at) desc
    limit 5
$$;

revoke execute on function public.recent_opponents() from public, anon;
grant execute on function public.recent_opponents() to authenticated;


-- =====================================================================
-- invites.sql
-- =====================================================================

-- Room invites. Run in the Supabase SQL Editor AFTER friends.sql (the block
-- check reads `friendships`). Additive: one table, one policy, three
-- SECURITY DEFINER functions, one publication change.
--
-- Reach is open by decision: anyone may invite anyone, and friendship is not
-- required. The controls that replace it are here - a block check, a cooldown
-- per pair, and an hourly cap per sender - because an open invite surface is
-- the first thing a pest finds.
--
-- Unlike `friendships`, this table has a SELECT policy. Realtime delivers
-- postgres_changes through RLS, so the recipient must be able to read their
-- own row or the subscription reports nothing. Writes still have no policy:
-- they go through send_room_invite, which is where the limits live.

create table if not exists room_invites (
    id uuid primary key default gen_random_uuid(),
    from_user uuid not null references auth.users(id) on delete cascade,
    to_user uuid not null references auth.users(id) on delete cascade,
    room_code text not null,
    -- What the room looked like when the invite was sent. A name alone makes
    -- the receiver guess whether they are joining a full table, an empty one,
    -- or a rules set they dislike.
    players smallint,
    mode text,
    created_at timestamptz not null default now(),
    -- Set when the recipient answers or dismisses. Keeps an answered invite
    -- from returning on the next page load.
    seen_at timestamptz
);

alter table room_invites add column if not exists players smallint;
alter table room_invites add column if not exists mode text;

create index if not exists room_invites_to_idx on room_invites (to_user, created_at desc);
create index if not exists room_invites_from_idx on room_invites (from_user, created_at desc);

alter table room_invites enable row level security;

drop policy if exists room_invites_read_own on room_invites;
create policy room_invites_read_own on room_invites
    for select using (to_user = auth.uid());

-- Realtime carries the invite to a player sitting on the home screen, where
-- the game socket does not exist. Adding a table twice raises, so the guard
-- keeps this file re-runnable.
do $$
begin
    alter publication supabase_realtime add table room_invites;
exception when duplicate_object then null;
end;
$$;

-- --- Write ------------------------------------------------------------------

-- Ask someone to your room. Returns: sent, blocked, self, too_soon,
-- rate_limited, not_found, bad_code, unauthorized.
--
-- The caller is the game server, not the player: p_from is supplied rather
-- than read from auth.uid(), and only service_role may execute. That is what
-- makes "X wants you at their table" a fact instead of a claim - the Durable
-- Object holds the sender's authenticated socket for that room, so it knows
-- they are actually sitting in it. A definer function reading auth.uid()
-- could only know who asked, never where they were.
--
-- Membership in the room is checked before this function is reached, by the
-- Durable Object that holds the sender's socket. What is left here is the
-- sender's conduct: is this pair blocked, is it too soon, is it too many.

drop function if exists public.send_room_invite(uuid, text);
drop function if exists public.send_room_invite(uuid, uuid, text);

create or replace function public.send_room_invite(p_from uuid, p_user uuid, p_code text, p_players int default null, p_mode text default null)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := p_from;
    recent int;
begin
    if me is null then return 'unauthorized'; end if;
    if p_user is null or p_user = me then return 'self'; end if;
    if p_code is null or p_code !~ '^[A-Za-z0-9]{4,12}$' then return 'bad_code'; end if;
    if not exists (select 1 from profiles where id = p_user) then return 'not_found'; end if;

    -- A block stops the invite whichever side placed it.
    if exists (
        select 1 from friendships
        where status = 'blocked'
          and least(requester_id, addressee_id) = least(me, p_user)
          and greatest(requester_id, addressee_id) = greatest(me, p_user)
    ) then return 'blocked'; end if;

    -- One invite per pair per five minutes. This is the rule that decides
    -- whether an unwanted invite is a nuisance or a barrage.
    if exists (
        select 1 from room_invites
        where from_user = me and to_user = p_user
          and created_at > now() - interval '5 minutes'
    ) then return 'too_soon'; end if;

    select count(*) into recent from room_invites
    where from_user = me and created_at > now() - interval '1 hour';
    if recent >= 20 then return 'rate_limited'; end if;

    -- Opportunistic sweep on the one path that writes. Both reads are time
    -- bounded - ten minutes for the toast, an hour for the cap - so nothing
    -- needs a row older than a day, and the table stays proportional to
    -- activity rather than to the age of the feature.
    delete from room_invites where created_at < now() - interval '1 day';

    insert into room_invites (from_user, to_user, room_code, players, mode)
    values (me, p_user, upper(p_code), greatest(0, least(coalesce(p_players, 0), 20)), left(coalesce(p_mode, ''), 16));
    return 'sent';
end;
$$;

-- No client path at all: the worker calls this with the service key.
revoke execute on function public.send_room_invite(uuid, uuid, text, int, text) from public, anon, authenticated;
grant execute on function public.send_room_invite(uuid, uuid, text, int, text) to service_role;

-- --- Reads ------------------------------------------------------------------

-- Invites worth showing: mine, unanswered, and young enough that the room is
-- probably still there. Ten minutes matches the public-room GC window in
-- game-server/src/roomGc.ts.

drop function if exists public.my_invites();

create or replace function public.my_invites()
returns table (
    id uuid,
    from_user uuid,
    from_username text,
    room_code text,
    players smallint,
    mode text,
    created_at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    select i.id, i.from_user, p.username, i.room_code, i.players, i.mode, i.created_at
    from room_invites i
    join profiles p on p.id = i.from_user
    where i.to_user = auth.uid()
      and i.seen_at is null
      and i.created_at > now() - interval '10 minutes'
    order by i.created_at desc
$$;

revoke execute on function public.my_invites() from public, anon;
grant execute on function public.my_invites() to authenticated;

-- Answered or waved away - either way it must not come back on reload.

create or replace function public.dismiss_invite(p_id uuid)
returns text
language plpgsql
security definer
set search_path = public
as $$
declare
    me uuid := auth.uid();
begin
    if me is null then return 'unauthorized'; end if;
    update room_invites set seen_at = now()
    where id = p_id and to_user = me and seen_at is null;
    if not found then return 'not_found'; end if;
    return 'dismissed';
end;
$$;

revoke execute on function public.dismiss_invite(uuid) from public, anon;
grant execute on function public.dismiss_invite(uuid) to authenticated;


-- =====================================================================
-- invites-sent.sql
-- =====================================================================

-- Invite status for the host. Run in the Supabase SQL Editor AFTER invites.sql.
-- Additive: one SECURITY DEFINER read. Re-runnable.
--
-- room_invites is readable only by its receiver (room_invites_read_own), and
-- widening that for the sender would be a second RLS exception. A definer
-- function instead returns exactly what the waiting room needs: the caller's
-- own invites for the room they are hosting, latest per person, and only the
-- two timestamps the status is built from.

create or replace function public.my_sent_invites(p_code text)
returns table (
    to_user uuid,
    created_at timestamptz,
    seen_at timestamptz
)
language sql
security definer
set search_path = public
stable
as $$
    select distinct on (i.to_user) i.to_user, i.created_at, i.seen_at
    from room_invites i
    where i.from_user = auth.uid()
      and i.room_code = p_code
      and i.created_at > now() - interval '30 minutes'
    order by i.to_user, i.created_at desc
$$;

revoke execute on function public.my_sent_invites(text) from public, anon;
grant execute on function public.my_sent_invites(text) to authenticated;


-- =====================================================================
-- pulse.sql
-- =====================================================================

-- Site pulse. Run in the Supabase SQL Editor. Additive: one index, one
-- SECURITY DEFINER function, one grant. Re-running the file is safe.
--
-- The landing page shows "733 PLAYERS · 5,544 GAMES THIS WEEK" to a cold
-- visitor, who otherwise has no way to tell whether anyone plays here. A
-- week is the window because it is always a big number: the live count in
-- the lobby (online_now) is honest about a quiet hour, and that honesty is
-- what sends a first-time visitor away. The client hides the line under a
-- floor, see frontend/src/composables/useSitePulse.ts.
--
-- What this exposes: two aggregate counts, no identities. Games are distinct
-- game ids, so a four-seat table counts once, not four times.

create index if not exists game_results_played_at_idx on game_results (played_at desc);

create or replace function public.site_pulse()
returns table (players_7d int, games_7d int)
language sql
security definer
set search_path = public
stable
as $$
    select count(distinct user_id)::int, count(distinct game_id)::int
    from game_results
    where played_at > now() - interval '7 days'
$$;

grant execute on function public.site_pulse to anon, authenticated;


-- =====================================================================
-- polls.sql
-- =====================================================================

-- One-question polls asked from the loud card. Run in the Supabase SQL
-- Editor. Additive: one table, RLS, and nothing else reads it.
--
-- The question itself is not here. It lives in
-- frontend/src/data/polls.ts, because asking is a deploy anyway and a table
-- would add a fetch and a policy to carry four lines of copy. This table
-- holds answers only.
--
-- Answers stay private. No policy exposes anyone else's vote, and there is
-- deliberately no results view: a view in `public` is reachable through the
-- API and does not enforce the underlying RLS unless it is declared
-- security_invoker, so publishing one would hand every vote to anon. Read the
-- tally in the SQL Editor with the queries at the bottom of this file.

create table if not exists public.poll_votes (
    poll_id text not null,
    user_id uuid not null default auth.uid() references auth.users on delete cascade,
    choice text not null check (length(choice) between 1 and 40),
    voted_at timestamptz not null default now(),
    primary key (poll_id, user_id)
);

alter table public.poll_votes enable row level security;

-- One vote per person, and only their own. `choice` is not checked against the
-- poll's options: the options live in the bundle, and duplicating them here
-- would put the same list in two places that drift. An option that was never
-- offered shows up as its own row in the tally below rather than silently
-- inflating a real one.
--
-- The cap this leaves: the anon key is public and anonymous sign-in mints
-- users freely, so the primary key stops a second vote from one account, not a
-- determined person from making more accounts. Read the tally with the
-- engaged-players query when the answer decides something expensive.
drop policy if exists "vote as yourself" on public.poll_votes;
create policy "vote as yourself"
    on public.poll_votes for insert
    to authenticated
    with check (auth.uid() = user_id);

drop policy if exists "read your own vote" on public.poll_votes;
create policy "read your own vote"
    on public.poll_votes for select
    to authenticated
    using (auth.uid() = user_id);

grant select, insert on public.poll_votes to authenticated;


-- Read the results ----------------------------------------------------------

-- The plain tally.
--
-- select choice, count(*) as votes
-- from poll_votes
-- where poll_id = '2026-08-29-mobile-app'
-- group by choice
-- order by votes desc;

-- The same tally, from players who have actually played. This join is the
-- reason the votes live next to game_results instead of in a hosted survey
-- tool: on a build-or-not question, the only answers worth weighting come from
-- people who play enough to use the thing.
--
-- select v.choice, count(*) as votes
-- from poll_votes v
-- join (
--     select user_id, count(*) as games
--     from game_results
--     where cards_played_total >= 5
--     group by user_id
-- ) g on g.user_id = v.user_id
-- where v.poll_id = '2026-08-29-mobile-app' and g.games >= 5
-- group by v.choice
-- order by votes desc;


-- =====================================================================
-- daily-suspects.sql
-- =====================================================================

-- Daily board: find likely fake scores. Read-only; run in the SQL Editor.
--
-- The browser plays the daily and reports the effort, so the server cannot
-- prove a score. What it can see: everyone plays the same deal, so the best
-- real line is usually found by several players and the top efforts cluster.
-- A fake shows up as a lone winner well below the rest of the day.
--
-- No fixed floor works instead: real wins at effort 2 exist (a Discard All
-- or a hand swap can end a game in two moves).
--
-- Flags a day's #1 who is alone at that effort and at least 3 below the
-- next winner, for the last 14 days. Review by hand before removing.

with wins as (
    select gr.id, gr.game_id, gr.user_id, p.username, gr.played_at,
           gr.cards_played_total + gr.draws_taken as effort,
           gr.game_duration_secs as duration_secs
    from game_results gr
    left join profiles p on p.id = gr.user_id
    where gr.game_id like 'daily-%'
      and gr.result = 'won'
      and gr.played_at > now() - interval '14 days'
), leaders as (
    select w.*,
           count(*) over (partition by game_id, effort) as tied,
           rank() over (partition by game_id order by effort) as rk,
           (select min(o.effort) from wins o where o.game_id = w.game_id and o.effort > w.effort) as next_best
    from wins w
)
select id, game_id, username, user_id, effort, next_best, duration_secs, played_at
from leaders
where rk = 1 and tied = 1 and next_best - effort >= 3
order by game_id desc;

-- To remove a confirmed fake (one row, by id from the result above):
-- delete from game_results where id = '<id>';


-- =====================================================================
-- username-suggestions.sql
-- =====================================================================

-- Available-name suggestions for a rejected rename.
-- Run in the Supabase SQL Editor. Additive: one SECURITY DEFINER function.
--
-- WHY THIS EXISTS
-- A player told only "that name is already taken" has to guess again. The logs
-- show that happening in clusters - one player made six attempts across three
-- minutes. Suggesting names they can actually have ends the guessing.
--
-- WHY IT IS CHECKED SERVER-SIDE
-- The client could append a random suffix without asking, and would be right
-- most of the time. But a suggestion that is itself taken is worse than no
-- suggestion, because the player already trusted it. `profiles` RLS is
-- owner-only, so testing availability needs a definer read - the same rule as
-- every other public read here. It returns only free names and never
-- enumerates the table, and usernames are already public on the leaderboard.

create or replace function public.username_suggestions(p_base text, p_count int default 3)
returns text[]
language plpgsql
security definer
set search_path = ''
as $$
declare
    base      text;
    candidate text;
    out_names text[] := '{}';
    attempt   int;
begin
    if p_count is null or p_count < 1 or p_count > 5 then
        p_count := 3;
    end if;

    -- Strip a trailing number so a rejected `Rahul7` suggests variants of
    -- `Rahul`, not of `Rahul7`. Capped at 15 so the 4-digit suffix keeps the
    -- whole name inside the 20 characters the input accepts.
    --
    -- The inner left() is the important one: this is granted to `anon` and the
    -- anon key is public, so p_base is whatever a request body carries, not
    -- something the 20-char input limited. Capping after the regex would let an
    -- arbitrarily long string be scanned first. 40 leaves room for a long name
    -- with a trailing number to still strip correctly.
    base := left(regexp_replace(left(coalesce(p_base, ''), 40), '[0-9]+$', ''), 15);
    if base = '' then
        base := 'Player';
    end if;

    -- Bounded: a caller must never be able to make this scan indefinitely.
    -- 40 tries against a 9000-wide suffix space finds 3 free names unless a
    -- base is extraordinarily popular, and returning fewer is fine - the
    -- caller renders what it gets.
    for attempt in 1..40 loop
        exit when coalesce(array_length(out_names, 1), 0) >= p_count;
        candidate := base || floor(random() * 9000 + 1000)::text;
        continue when candidate = any(out_names);
        if not exists (select 1 from public.profiles p where p.username = candidate) then
            out_names := out_names || candidate;
        end if;
    end loop;

    return out_names;
end;
$$;

grant execute on function public.username_suggestions to anon, authenticated;

-- Suggestions can go stale between being offered and being tapped, so the
-- unique constraint stays the real guard and the taken-name error still shows.
-- That is the correct division: this improves the odds, it does not replace
-- the check.

-- Sanity check. Expect 3 names built on 'Rahul', and 3 on 'Player' for junk
-- input. Run after creating the function.
--   select public.username_suggestions('Rahul') as normal,
--          public.username_suggestions('Rahul7') as strips_trailing_digits,
--          public.username_suggestions('') as empty_base,
--          public.username_suggestions('Rahul', 99) as count_clamped;


-- Make the new tables and functions visible to the API right away.
notify pgrst, 'reload schema';
